package com.aig.feature.cam
import android.content.Context
import android.graphics.Color
import android.text.InputType
import android.widget.*
import com.aig.core.cam.*
import com.aig.core.ui.R as UiR
import com.aig.core.ui.UiKit
object CamFeatureView{private fun field(c:Context,h:String,v:String)=EditText(c).apply{hint=h;setText(v);setTextColor(Color.WHITE);setHintTextColor(Color.GRAY);setBackgroundColor(Color.rgb(7,17,27));inputType=InputType.TYPE_CLASS_NUMBER or InputType.TYPE_NUMBER_FLAG_DECIMAL or InputType.TYPE_NUMBER_FLAG_SIGNED;setPadding(UiKit.dp(c,8),UiKit.dp(c,6),UiKit.dp(c,8),UiKit.dp(c,6))};private fun num(v:EditText,d:Double)=v.text.toString().toDoubleOrNull()?:d;fun create(c:Context):LinearLayout{var s=CamState(path=listOf(ManualCamPoint(0.0,0.0,3.0,Motion.G0,10.0,20.0,30.0),ManualCamPoint(0.0,0.0,-5.0,Motion.G1,10.0,20.0,30.0),ManualCamPoint(30.0,0.0,-5.0,Motion.G1,10.0,20.0,30.0)));val r=UiKit.column(c);r.addView(UiKit.skinBanner(c,UiR.drawable.aig_cam,76));val st=UiKit.statusLabel(c,"CAM • MANUAL FIRST • Safe-Z 3.000");r.addView(st);val m=UiKit.toolGrid(c,4);UiKit.addGridButton(m,"MANUAL"){s=s.copy(source=CamSource.MANUAL)};UiKit.addGridButton(m,"AUTO"){s=s.copy(source=CamSource.AUTO)};UiKit.addGridButton(m,"G41"){s=s.copy(cutterComp=CutterComp.G41)};UiKit.addGridButton(m,"G42"){s=s.copy(cutterComp=CutterComp.G42)};UiKit.addGridButton(m,"內徑"){s=s.copy(cutSide=CutSide.INNER)};UiKit.addGridButton(m,"外徑"){s=s.copy(cutSide=CutSide.OUTER)};UiKit.addGridButton(m,"順銑"){s=s.copy(direction=CutDirection.CLIMB)};UiKit.addGridButton(m,"逆銑"){s=s.copy(direction=CutDirection.CONVENTIONAL)};r.addView(m);val p=LinearLayout(c).apply{orientation=LinearLayout.HORIZONTAL};val safe=field(c,"Safe-Z",s.safeZ.toString());val dia=field(c,"刀徑",s.toolDiameter.toString());val dep=field(c,"深度",s.depth.toString());val feed=field(c,"進給",s.feed.toString());listOf(safe,dia,dep,feed).forEach{p.addView(it,LinearLayout.LayoutParams(0,LinearLayout.LayoutParams.WRAP_CONTENT,1f))};r.addView(p);val ed=LinearLayout(c).apply{orientation=LinearLayout.HORIZONTAL};val idx=field(c,"節點","1");val x=field(c,"X","0.0");val y=field(c,"Y","0.0");val z=field(c,"Z","-5.0");listOf(idx,x,y,z).forEach{ed.addView(it,LinearLayout.LayoutParams(0,LinearLayout.LayoutParams.WRAP_CONTENT,1f))};r.addView(ed);val t=TextView(c).apply{setTextColor(Color.rgb(210,240,250));textSize=12f;setBackgroundColor(Color.rgb(3,10,16))};fun render(){t.text=s.path.mapIndexed{i,q->"%02d %s X%.3f Y%.3f Z%.3f A%.3f B%.3f C%.3f".format(i,q.motion,q.x,q.y,q.z,q.axisA,q.axisB,q.axisC)}.joinToString("\n");st.text="CAM • ${s.source} • Safe-Z ${"%.3f".format(s.safeZ)} • ${s.cutterComp} • ${s.cutSide} • ${s.direction}"};val a=UiKit.toolGrid(c,4);UiKit.addGridButton(a,"套用參數"){s=s.copy(safeZ=num(safe,s.safeZ),toolDiameter=num(dia,s.toolDiameter),depth=num(dep,s.depth),feed=num(feed,s.feed));render()};UiKit.addGridButton(a,"更新節點"){val i=idx.text.toString().toIntOrNull()?:0;if(i in s.path.indices){val q=s.path[i];s=CamWorkflow.updatePoint(s,i,q.copy(x=num(x,q.x),y=num(y,q.y),z=num(z,q.z)));render()}};UiKit.addGridButton(a,"G0/G1"){val i=idx.text.toString().toIntOrNull()?:0;if(i in s.path.indices){val q=s.path[i];s=CamWorkflow.updatePoint(s,i,q.copy(motion=if(q.motion==Motion.G0)Motion.G1 else Motion.G0));render()}};UiKit.addGridButton(a,"避讓壓板"){if(s.source!=CamSource.MANUAL)s=s.copy(source=CamSource.MANUAL);val i=(idx.text.toString().toIntOrNull()?:0).coerceIn(0,s.path.lastIndex);s=CamWorkflow.insertFixtureBypass(s,i,10.0,10.0,20.0,20.0,s.depth);render()};r.addView(a);r.addView(t,LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,0,1f));render();return r}}
